// Einmaliger Nachtrag 2026-07-28: extrahiert Verfasser/Fachdienst/PDF-Datum aus dem
// bereits vorhandenen combinedText (kein Re-Scrape) fuer alle Zeilen, die noch keinen
// vorlageDatum-Wert haben - identische Extraktionslogik wie in P3 "NC Aggregiere Texte".
// vorlageDatumWeb (aus P1/Beratungsfolge) existiert fuer diese Alt-Zeilen noch nicht,
// daher hier ausschliesslich PDF-Datum als vorlageDatum verwendet.

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

function extractVorlagenMeta(text) {
  const t = safeStr(text);
  const verfasserMatch = t.match(/([^\n]+)\n\s*Verfasser\/in/);
  const datumMatch = t.match(/Stadt Goslar Goslar,\s*(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  let fachdienst = '';
  if (datumMatch) {
    const rest = t.slice(datumMatch.index + datumMatch[0].length);
    const fdMatch = rest.match(/^\s*\n([^\n]+)\n/);
    if (fdMatch) fachdienst = fdMatch[1].trim();
  }
  const vorlageDatumPdf = datumMatch
    ? `${datumMatch[3]}-${datumMatch[2].padStart(2, '0')}-${datumMatch[1].padStart(2, '0')}`
    : '';
  return { verfasser: verfasserMatch ? verfasserMatch[1].trim() : '', fachdienst, vorlageDatumPdf };
}

const out = [];
for (const item of items) {
  const j = item.json || {};
  if (safeStr(j.vorlageDatum)) continue; // schon gesetzt (z.B. durch einen neueren P3-Lauf), nicht anfassen
  if (!safeStr(j.combinedText)) continue; // nichts zu extrahieren
  const meta = extractVorlagenMeta(j.combinedText);
  if (!meta.vorlageDatumPdf && !meta.verfasser && !meta.fachdienst) continue; // Muster nicht gefunden
  out.push({
    json: {
      vorgangKey: j.vorgangKey,
      vorgangsnummer: j.vorgangsnummer,
      verfasser: meta.verfasser,
      fachdienst: meta.fachdienst,
      vorlageDatumPdf: meta.vorlageDatumPdf,
      vorlageDatum: meta.vorlageDatumPdf
    }
  });
}
return out;
